import numpy as np

def prime_table(N):
    is_prime = np.ones(N, dtype=bool)
    is_prime[:2] = False
    for p in range(2, int(N**0.5) + 1):
        if is_prime[p]:
            is_prime[p*p::p] = False
    return np.flatnonzero(is_prime)

def main(N, primes):
    div = np.ones(N + 1, dtype=np.int64)
    for p in primes:
        if p > N:
            break
        for i in range(p, N + 1, p):
            div[i] += div[i // p]
    div *= np.arange(N + 1)
    return div.sum()

