from collections import Counter

def factors(n):
    d = Counter()
    for i in range(2, floor(sqrt(n)) + 1):
        while n % i == 0:
            n //= i
            d[i] += 1
        if n == 1:
            break
    if n != 1:
        d[n] += 1
    return d

def inv(x, mod):
    k = mod - 2
    ret = 1
    while k > 0:
        if k & 1:
            ret = (ret * x) % mod
        x = (x * x) % mod
        k >>= 1
    return ret

