def segfunc(x, y): return max(x, y)

class SegmentTree:
    def __init__(self, arr):
        size = len(arr)
        self.n = size
        self.node = defaultdict(int)
        for i in range(size):
            self.node[i] = arr[i]
        for i in reversed(range(1, size)):
            self.node[i] = segfunc(self.node[2*i], self.node[2*i+1])

    def update(self, i, x):
        i += self.n
        self.node[i] = x
        while i > 1:
            i //= 2
            self.node[i] = segfunc(self.node[2*i], self.node[2*i+1])

    def query(self, a, b):
        res = 0
        l = a + self.n
        r = b + self.n
        while l < r:
            if l & 1:
                res = segfunc(res, self.node[l])
                l += 1
            if r & 1:
                r -= 1
                res = segfunc(res, self.node[r])
            l //= 2
            r //= 2
        return res

