class BinaryIndexedTree:
    def __init__(self, n):
        self.n = n
        self.bit = [0] * (n + 1)
        self.data = [0] * (n + 1)

    def add(self, i, v):
        while i <= self.n:
            self.bit[i] += v
            i += i & -i

    def sum(self, i):
        rst = 0
        while i > 0:
            rst += self.bit[i]
            i -= i & -i
        return rst

    def get(self, i, j):
        return self.sum(j) - self.sum(i - 1)

    def update(self, i, v):
        self.add(i, v - self.data[i])
        self.data[i] = v

