class Calc:
    def __init__(self, max_value, mod):
        self.fact = [1] * (max_value + 1)
        self.invs = [1] * (max_value + 1)
        self.mod = mod

        for x in range(2, max_value + 1):
            self.fact[x] = x * self.fact[x - 1] % mod

        self.invs[max_value] = pow(self.fact[max_value], mod - 2, mod)

        for x in range(max_value - 1, 0, -1):
            self.invs[x] = self.invs[x + 1] * (x + 1) % mod

    def combination(self, n, r):
        if n - r < r:
            return self.combination(n, n - r)
        if r < 0:
            return 0
        if r == 0:
            return 1
        if r == 1:
            return n
        return self.fact[n] * self.invs[r] * self.invs[n - r] % self.mod

