def solve(N: int, K: int, A: "List[int]", F: "List[int]"):
    A.sort()
    F.sort(reverse=True)
    h = []
    for a, f in zip(A, F):
        h.append((a*f, a, f))
    h.sort()
    prefix_sum = [0] * (N+1)
    for i in range(N):
        prefix_sum[i+1] = prefix_sum[i] + h[i][1]
    maxtime = h[-1][0]
    def isOK(y):
        i = bisect_left(h, (y+1, -1, -1))
        counter = 0
        for p, a, f in h[i:]:
            counter += a - (prefix_sum[bisect_left(h, (y//f, -1, -1))] - prefix_sum[i])
        return counter <= K
    def binary_search(x):
        ng = -1
        ok = len(x)
        while abs(ok - ng) > 1:
            mid = (ok + ng)//2
            if isOK(mid):
                ok = mid
            else:
                ng = mid
        return ng, ok
    ng, ok = binary_search(list(range(maxtime)))
    print(ok)

